import{_ as e,c as r,o,ah as d}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Настройки логов","description":"","frontmatter":{"title":"Настройки логов"},"headers":[],"relativePath":"ru/logs/settings.md","filePath":"ru/logs/settings.md"}'),a={name:"ru/logs/settings.md"};function s(n,t,g,i,h,l){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="настроики-логов" tabindex="-1">Настройки логов <a class="header-anchor" href="#настроики-логов" aria-label="Permalink to &quot;Настройки логов&quot;">​</a></h1><p>В <strong>Options → Logs</strong> собраны настройки вкладки <a href="./general.html">Logs</a>. Изменения применяются сразу.</p><hr><h2 id="search-settings" tabindex="-1">Search Settings <a class="header-anchor" href="#search-settings" aria-label="Permalink to &quot;Search Settings&quot;">​</a></h2><p>Режимы поиска вкладки <strong>Logs</strong> по умолчанию:</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Где ищет</th></tr></thead><tbody><tr><td><strong>Search by event name</strong></td><td>Заголовок, компонент, стор, URL (включён по умолчанию)</td></tr><tr><td><strong>Search by key</strong></td><td>Ключи в данных события и пути изменений</td></tr><tr><td><strong>Search by value</strong></td><td>Значения в данных события</td></tr></tbody></table><hr><h2 id="ignore-list" tabindex="-1">Ignore list <a class="header-anchor" href="#ignore-list" aria-label="Permalink to &quot;Ignore list&quot;">​</a></h2><p>Группы событий, добавленные через <strong>Ignore</strong> во вкладке <strong>Logs</strong>. События этих групп не записываются.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Содержимое</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td>Тип события</td></tr><tr><td><strong>Event</strong></td><td>Ключ группы: запрос (метод и путь), компонент, стор и т.д.</td></tr><tr><td><strong>Added</strong></td><td>Дата добавления правила</td></tr></tbody></table><ul><li><strong>Log again</strong> в меню строки снимает одно правило.</li><li><strong>Log all again</strong> снимает все правила.</li></ul><p>Тот же список доступен через индикатор <strong>ignored</strong> на панели вкладки <strong>Logs</strong>.</p><hr><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Формат <strong>Export Logs</strong> и экспорта одного события:</p><ul><li><strong>JSON</strong> — исходные события для повторного импорта или сторонних инструментов;</li><li><strong>HTML</strong> (по умолчанию) — статический отчёт, открывается в любом браузере и импортируется обратно.</li></ul><p>Подробнее: <a href="./export.html">Экспорт и импорт</a>.</p><hr><h2 id="logs-limits" tabindex="-1">Logs limits <a class="header-anchor" href="#logs-limits" aria-label="Permalink to &quot;Logs limits&quot;">​</a></h2><p>Каждый тип событий — <strong>кольцевой буфер</strong>: при заполнении самые старые события перезаписываются. Бюджет памяти общий для всех типов.</p><h3 id="events-per-type" tabindex="-1">Events per type <a class="header-anchor" href="#events-per-type" aria-label="Permalink to &quot;Events per type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Тип</th><th>По умолчанию</th><th>Единица</th></tr></thead><tbody><tr><td><strong>Network</strong></td><td>500</td><td>запросов</td></tr><tr><td><strong>Props changes</strong></td><td>1 000</td><td>событий</td></tr><tr><td><strong>Emits</strong></td><td>1 000</td><td>событий</td></tr><tr><td><strong>Pinia changes</strong></td><td>1 000</td><td>событий</td></tr><tr><td><strong>Store actions</strong></td><td>1 000</td><td>событий</td></tr><tr><td><strong>Navigation</strong></td><td>200</td><td>событий</td></tr><tr><td><strong>JS errors</strong></td><td>200</td><td>событий</td></tr></tbody></table><p>Допустимый диапазон: <strong>10 – 20 000</strong>. Число перед полем показывает, сколько событий этого типа хранится сейчас. Для <strong>Network</strong> лимит действует отдельно для событий <strong>Send request</strong> и <strong>Receive response</strong>.</p><h3 id="data-size" tabindex="-1">Data size <a class="header-anchor" href="#data-size" aria-label="Permalink to &quot;Data size&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Диапазон</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Memory budget</strong></td><td>64 МБ</td><td>8 – 1024 МБ</td><td>Общий объём всех событий в буфере (приблизительный размер после сериализации)</td></tr><tr><td><strong>Max event size</strong></td><td>512 КБ</td><td>16 – 16 384 КБ</td><td>Крупные части события (снимки стора, аргументы, результаты) отбрасываются, сетевые тела обрезаются до этого размера</td></tr></tbody></table><p>Полоса под полями показывает текущее использование (<strong>Used X of Y</strong>); выше 90 % она становится оранжевой.</p><p>Значения вне диапазона приводятся к ближайшей границе. <strong>Defaults</strong> восстанавливает все лимиты.</p><hr><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking {#data-masking}&quot;">​</a></h2><p>Значения маскируются <strong>в момент записи события</strong>, поэтому не попадают ни в интерфейс <strong>Logs</strong>, ни в экспорт, ни в импорт.</p><table tabindex="0"><thead><tr><th>Параметр</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Mask sensitive data</strong></td><td>Включает маскирование (включено по умолчанию)</td></tr><tr><td><strong>Mask token-like values in any text</strong></td><td>Маскирует <strong>JWT</strong>, учётные данные <strong>Bearer</strong> / <strong>Basic</strong> и номера карт внутри любой строки</td></tr><tr><td>Список <strong>Key contains</strong></td><td>Ключи объектов, имена заголовков и параметров, содержащие эти фрагменты, маскируются</td></tr></tbody></table><p>Ключи по умолчанию: <code>password</code>, <code>passwd</code>, <code>pwd</code>, <code>secret</code>, <code>token</code>, <code>authorization</code>, <code>cookie</code>, <code>apikey</code>, <code>sessionid</code>, <code>privatekey</code>, <code>creditcard</code>, <code>cardnumber</code>, <code>cvv</code>, <code>cvc</code>, <code>ssn</code>, <code>otp</code>.</p><p>Сравнение ключей не учитывает регистр и разделители (<code>api_key</code>, <code>api-key</code> и <code>apiKey</code> — одно и то же). Фрагменты из <strong>4 букв и короче</strong> должны совпадать с целым словом, поэтому <code>pwd</code> или <code>otp</code> не маскируют посторонние ключи.</p><p>Свои фрагменты добавляются в поле под списком, удаляются через меню строки. <strong>Default keys</strong> восстанавливает список по умолчанию.</p><p>Замаскированные значения заменяются метками: <code>[MASKED]</code> — для значений чувствительных ключей, <code>[MASKED JWT]</code> и <code>[MASKED CARD]</code> — для токенов и номеров карт, найденных в тексте (номера карт проверяются алгоритмом Луна).</p><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./general.html">Работа с логами</a></li><li><a href="./export.html">Экспорт и импорт</a></li><li><a href="/qa-tools/docs/ru/options/settings_management.html">Менеджер настроек</a></li></ul>',38)])])}const b=e(a,[["render",s]]);export{p as __pageData,b as default};
